/**
 * IMU 数据管理模块
 * 负责加速度计和陀螺仪数据的采集、同步和缓冲
 */

import sensor from '@system.sensor'
import { SAMPLING_CONFIG, DEFAULT_THRESHOLDS } from './constants'

class IMUManager {
  constructor() {
    this.isRunning = false
    this.accelData = { x: 0, y: 0, z: 0, timestamp: 0 }
    this.gyroData = { x: 0, y: 0, z: 0, timestamp: 0 }
    this.buffer = []
    this.maxBufferSize = SAMPLING_CONFIG.BUFFER_SIZE
    this.listeners = []
  }

  /**
   * 订阅加速度计数据
   */
  subscribeAccelerometer() {
    sensor.subscribeAccelerometer({
      interval: SAMPLING_CONFIG.INTERVAL,
      callback: (data) => {
        this.accelData = {
          x: data.x,
          y: data.y,
          z: data.z,
          timestamp: Date.now()
        }
        this.syncData()
      },
      fail: (data, code) => {
        console.error(`加速度计订阅失败: ${code}`)
      }
    })
  }

  /**
   * 订阅陀螺仪数据
   */
  subscribeGyroscope() {
    sensor.subscribeGyroscope({
      interval: SAMPLING_CONFIG.INTERVAL,
      callback: (data) => {
        this.gyroData = {
          x: data.x,
          y: data.y,
          z: data.z,
          timestamp: Date.now()
        }
        this.syncData()
      },
      fail: (data, code) => {
        console.error(`陀螺仪订阅失败: ${code}`)
      }
    })
  }

  /**
   * 数据同步 - 将加速度和角速度数据合并
   */
  syncData() {
    // 确保两个传感器都有数据
    if (this.accelData.timestamp === 0 || this.gyroData.timestamp === 0) {
      return
    }

    const syncData = {
      accel: { ...this.accelData },
      gyro: { ...this.gyroData },
      timestamp: Date.now()
    }

    // 添加到缓冲区
    this.buffer.push(syncData)

    // 缓冲区满时移除最早的数据
    if (this.buffer.length > this.maxBufferSize) {
      this.buffer.shift()
    }

    // 通知监听器
    this.notifyListeners(syncData)
  }

  /**
   * 启动 IMU 数据采集
   */
  start() {
    if (this.isRunning) {
      console.log('IMU 已在运行中')
      return
    }

    this.isRunning = true
    this.buffer = []
    this.subscribeAccelerometer()
    this.subscribeGyroscope()
    console.log('IMU 数据采集已启动')
  }

  /**
   * 停止 IMU 数据采集
   */
  stop() {
    if (!this.isRunning) {
      return
    }

    this.isRunning = false
    sensor.unsubscribeAccelerometer()
    sensor.unsubscribeGyroscope()
    console.log('IMU 数据采集已停止')
  }

  /**
   * 获取当前数据
   */
  getCurrentData() {
    return {
      accel: { ...this.accelData },
      gyro: { ...this.gyroData }
    }
  }

  /**
   * 获取缓冲区数据
   */
  getBuffer() {
    return [...this.buffer]
  }

  /**
   * 清空缓冲区
   */
  clearBuffer() {
    this.buffer = []
  }

  /**
   * 添加数据监听器
   */
  addListener(callback) {
    this.listeners.push(callback)
  }

  /**
   * 移除数据监听器
   */
  removeListener(callback) {
    this.listeners = this.listeners.filter(cb => cb !== callback)
  }

  /**
   * 通知所有监听器
   */
  notifyListeners(data) {
    this.listeners.forEach(cb => {
      try {
        cb(data)
      } catch (e) {
        console.error('监听器回调错误:', e)
      }
    })
  }

  /**
   * 计算加速度幅值
   */
  getAccelMagnitude(accel) {
    return Math.sqrt(accel.x * accel.x + accel.y * accel.y + accel.z * accel.z)
  }

  /**
   * 计算角速度幅值
   */
  getGyroMagnitude(gyro) {
    return Math.sqrt(gyro.x * gyro.x + gyro.y * gyro.y + gyro.z * gyro.z)
  }
}

// 导出单例
export default new IMUManager()

/**
 * 健康数据管理模块
 * 负责心率监测、卡路里计算和运动时长统计
 */

import health from '@system.health'
import { STORAGE_KEYS } from './constants'

class HealthMonitor {
  constructor() {
    this.isRunning = false
    this.heartRate = null
    this.calories = 0
    this.duration = 0
    this.startTime = null
    this.timer = null
    this.listeners = []
    this.weight = 70 // 默认体重，用于卡路里计算
  }

  /**
   * 订阅心率数据
   */
  subscribeHeartRate() {
    health.subscribeSample({
      dataType: 0, // HEART_RATE
      callback: (data) => {
        this.heartRate = data.value
        this.notifyListeners({
          type: 'heartRate',
          value: data.value
        })
      },
      fail: (data, code) => {
        console.error(`心率订阅失败: ${code}`)
      }
    })
  }

  /**
   * 启动健康监测
   */
  start() {
    if (this.isRunning) {
      console.log('健康监测已在运行中')
      return
    }

    this.isRunning = true
    this.startTime = Date.now()
    this.duration = 0
    this.calories = 0

    this.subscribeHeartRate()
    this.startDurationTimer()
    console.log('健康监测已启动')
  }

  /**
   * 停止健康监测
   */
  stop() {
    if (!this.isRunning) {
      return
    }

    this.isRunning = false
    health.unsubscribeSample()
    this.stopDurationTimer()
    console.log('健康监测已停止')
  }

  /**
   * 启动时长计时器
   */
  startDurationTimer() {
    this.timer = setInterval(() => {
      this.updateDuration()
      this.updateCalories()
    }, 1000)
  }

  /**
   * 停止时长计时器
   */
  stopDurationTimer() {
    if (this.timer) {
      clearInterval(this.timer)
      this.timer = null
    }
  }

  /**
   * 更新运动时长
   */
  updateDuration() {
    if (!this.startTime) return
    this.duration = Math.floor((Date.now() - this.startTime) / 1000)
    this.notifyListeners({
      type: 'duration',
      value: this.formatDuration(this.duration)
    })
  }

  /**
   * 更新卡路里消耗
   * 使用简化的 MET 公式计算
   */
  updateCalories() {
    if (!this.startTime) return

    // 羽毛球运动的 MET 值约为 5.5
    const MET = 5.5
    const hours = this.duration / 3600
    // 卡路里 = MET × 体重(kg) × 时间(小时)
    this.calories = Math.round(MET * this.weight * hours)

    this.notifyListeners({
      type: 'calories',
      value: this.calories
    })
  }

  /**
   * 格式化时长
   */
  formatDuration(seconds) {
    const mins = Math.floor(seconds / 60).toString().padStart(2, '0')
    const secs = (seconds % 60).toString().padStart(2, '0')
    return `${mins}:${secs}`
  }

  /**
   * 设置体重
   */
  setWeight(weight) {
    this.weight = weight
  }

  /**
   * 获取当前心率
   */
  getHeartRate() {
    return this.heartRate
  }

  /**
   * 获取卡路里
   */
  getCalories() {
    return this.calories
  }

  /**
   * 获取运动时长
   */
  getDuration() {
    return this.formatDuration(this.duration)
  }

  /**
   * 添加数据监听器
   */
  addListener(callback) {
    this.listeners.push(callback)
  }

  /**
   * 移除数据监听器
   */
  removeListener(callback) {
    this.listeners = this.listeners.filter(cb => cb !== callback)
  }

  /**
   * 通知所有监听器
   */
  notifyListeners(data) {
    this.listeners.forEach(cb => {
      try {
        cb(data)
      } catch (e) {
        console.error('监听器回调错误:', e)
      }
    })
  }
}

// 导出单例
export default new HealthMonitor()

/**
 * 传感器数据融合模块
 * 负责加速度与角速度数据融合、校准和滤波
 */

import { DEFAULT_THRESHOLDS } from './constants'

class SensorFusion {
  constructor() {
    // 零偏校准值
    this.accelOffset = { x: 0, y: 0, z: 0 }
    this.gyroOffset = { x: 0, y: 0, z: 0 }

    // 滤波器状态
    this.filteredAccel = { x: 0, y: 0, z: 0 }
    this.filteredGyro = { x: 0, y: 0, z: 0 }

    // 滤波系数 (0-1, 越小越平滑)
    this.filterCoeff = 0.3

    // 是否已校准
    this.isCalibrated = false
  }

  /**
   * 零偏校准
   * 在静止状态下采集数据，计算零偏
   */
  calibrate(accelSamples, gyroSamples) {
    if (accelSamples.length === 0 || gyroSamples.length === 0) {
      console.error('校准数据不足')
      return false
    }

    // 计算加速度零偏
    const accelSum = accelSamples.reduce((sum, s) => ({
      x: sum.x + s.x,
      y: sum.y + s.y,
      z: sum.z + s.z
    }), { x: 0, y: 0, z: 0 })

    this.accelOffset = {
      x: accelSum.x / accelSamples.length,
      y: accelSum.y / accelSamples.length,
      z: (accelSum.z / accelSamples.length) - 9.8 // 减去重力加速度
    }

    // 计算角速度零偏
    const gyroSum = gyroSamples.reduce((sum, s) => ({
      x: sum.x + s.x,
      y: sum.y + s.y,
      z: sum.z + s.z
    }), { x: 0, y: 0, z: 0 })

    this.gyroOffset = {
      x: gyroSum.x / gyroSamples.length,
      y: gyroSum.y / gyroSamples.length,
      z: gyroSum.z / gyroSamples.length
    }

    this.isCalibrated = true
    console.log('传感器校准完成')
    return true
  }

  /**
   * 校准原始数据
   */
  calibrateData(accel, gyro) {
    return {
      accel: {
        x: accel.x - this.accelOffset.x,
        y: accel.y - this.accelOffset.y,
        z: accel.z - this.accelOffset.z
      },
      gyro: {
        x: gyro.x - this.gyroOffset.x,
        y: gyro.y - this.gyroOffset.y,
        z: gyro.z - this.gyroOffset.z
      }
    }
  }

  /**
   * 低通滤波器
   * 用于平滑数据，减少噪声
   */
  lowPassFilter(current, previous, alpha) {
    return {
      x: alpha * current.x + (1 - alpha) * previous.x,
      y: alpha * current.y + (1 - alpha) * previous.y,
      z: alpha * current.z + (1 - alpha) * previous.z
    }
  }

  /**
   * 应用滤波
   */
  applyFilter(accel, gyro) {
    this.filteredAccel = this.lowPassFilter(accel, this.filteredAccel, this.filterCoeff)
    this.filteredGyro = this.lowPassFilter(gyro, this.filteredGyro, this.filterCoeff)

    return {
      accel: { ...this.filteredAccel },
      gyro: { ...this.filteredGyro }
    }
  }

  /**
   * 融合处理
   * 完整的数据处理流水线：校准 → 滤波
   */
  fuse(rawAccel, rawGyro) {
    // 1. 校准
    const calibrated = this.calibrateData(rawAccel, rawGyro)

    // 2. 滤波
    const filtered = this.applyFilter(calibrated.accel, calibrated.gyro)

    return {
      accel: filtered.accel,
      gyro: filtered.gyro,
      magnitude: {
        accel: this.getMagnitude(filtered.accel),
        gyro: this.getMagnitude(filtered.gyro)
      }
    }
  }

  /**
   * 计算向量幅值
   */
  getMagnitude(vector) {
    return Math.sqrt(vector.x * vector.x + vector.y * vector.y + vector.z * vector.z)
  }

  /**
   * 检测运动强度
   */
  getIntensityLevel(accelMagnitude) {
    if (accelMagnitude < 5) return 'low'
    if (accelMagnitude < 15) return 'medium'
    return 'high'
  }

  /**
   * 重置滤波器
   */
  resetFilter() {
    this.filteredAccel = { x: 0, y: 0, z: 0 }
    this.filteredGyro = { x: 0, y: 0, z: 0 }
  }
}

