export default new SensorFusion()

/**
 * 数据存储模块
 * 负责本地数据的存储、查询和导出
 */

import storage from '@system.storage'
import { STORAGE_KEYS } from './constants'

class DataStore {
  constructor() {
    this.settings = null
    this.sessions = []
    this.currentSession = null
  }

  /**
   * 初始化数据存储
   */
  init() {
    this.loadSettings()
    this.loadSessions()
  }

  /**
   * 加载设置
   */
  loadSettings() {
    storage.get({
      key: STORAGE_KEYS.SETTINGS,
      success: (data) => {
        this.settings = JSON.parse(data)
        console.log('设置加载成功')
      },
      fail: (data, code) => {
        console.log('设置不存在，使用默认值')
        this.settings = this.getDefaultSettings()
      }
    })
  }

  /**
   * 保存设置
   */
  saveSettings(settings) {
    this.settings = settings
    storage.set({
      key: STORAGE_KEYS.SETTINGS,
      value: JSON.stringify(settings),
      success: () => {
        console.log('设置保存成功')
      },
      fail: (data, code) => {
        console.error(`设置保存失败: ${code}`)
      }
    })
  }

  /**
   * 获取默认设置
   */
  getDefaultSettings() {
    return {
      accelThreshold: 15,
      gyroThreshold: 200,
      weight: 70,
      age: 25
    }
  }

  /**
   * 加载历史会话
   */
  loadSessions() {
    storage.get({
      key: STORAGE_KEYS.SESSIONS,
      success: (data) => {
        this.sessions = JSON.parse(data)
        console.log(`加载了 ${this.sessions.length} 个历史会话`)
      },
      fail: (data, code) => {
        console.log('历史会话不存在')
        this.sessions = []
      }
    })
  }

  /**
   * 保存历史会话
   */
  saveSessions() {
    storage.set({
      key: STORAGE_KEYS.SESSIONS,
      value: JSON.stringify(this.sessions),
      success: () => {
        console.log('历史会话保存成功')
      },
      fail: (data, code) => {
        console.error(`历史会话保存失败: ${code}`)
      }
    })
  }

  /**
   * 开始新的会话
   */
  startSession() {
    this.currentSession = {
      id: Date.now().toString(),
      startTime: Date.now(),
      endTime: null,
      duration: 0,
      swingCount: 0,
      calories: 0,
      shotTypes: {
        highClear: 0,
        smash: 0,
        drive: 0,
        lift: 0,
        drop: 0
      }
    }
    console.log('新会话已创建')
  }

  /**
   * 结束当前会话
   */
  endSession() {
    if (!this.currentSession) return

    this.currentSession.endTime = Date.now()
    this.currentSession.duration = Math.floor(
      (this.currentSession.endTime - this.currentSession.startTime) / 1000
    )

    this.sessions.unshift(this.currentSession)

    // 只保留最近 100 个会话
    if (this.sessions.length > 100) {
      this.sessions = this.sessions.slice(0, 100)
    }

    this.saveSessions()
    console.log('会话已保存')
  }

  /**
   * 记录挥拍
   */
  recordSwing(shotType) {
    if (!this.currentSession) return

    this.currentSession.swingCount++
    if (this.currentSession.shotTypes[shotType] !== undefined) {
      this.currentSession.shotTypes[shotType]++
    }
  }

  /**
   * 更新卡路里
   */
  updateCalories(calories) {
    if (!this.currentSession) return
    this.currentSession.calories = calories
  }

  /**
   * 获取今日统计
   */
  getTodayStats() {
    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const todayTimestamp = today.getTime()

    const todaySessions = this.sessions.filter(s =>
      s.startTime >= todayTimestamp
    )

    return {
      totalSwings: todaySessions.reduce((sum, s) => sum + s.swingCount, 0),
      duration: this.formatTotalDuration(
        todaySessions.reduce((sum, s) => sum + s.duration, 0)
      ),
      calories: todaySessions.reduce((sum, s) => sum + s.calories, 0)
    }
  }

  /**
   * 获取击球类型分布
   */
  getShotDistribution() {
    const distribution = {
      highClear: 0,
      smash: 0,
      drive: 0,
      lift: 0,
      drop: 0
    }

    this.sessions.forEach(s => {
      Object.keys(s.shotTypes).forEach(type => {
        distribution[type] += s.shotTypes[type]
      })
    })

    return distribution
  }

  /**
   * 格式化总时长
   */
  formatTotalDuration(seconds) {
    const hours = Math.floor(seconds / 3600)
    const mins = Math.floor((seconds % 3600) / 60)

    if (hours > 0) {
      return `${hours}小时${mins}分钟`
    }
    return `${mins}分钟`
  }

  /**
   * 导出数据
   */
  exportData() {
    return JSON.stringify({
      settings: this.settings,
      sessions: this.sessions,
      exportTime: new Date().toISOString()
    }, null, 2)
  }

  /**
   * 清除所有数据
   */
  clearAllData() {
    this.settings = this.getDefaultSettings()
    this.sessions = []
    this.currentSession = null

    storage.clear({
      success: () => {
        console.log('数据已清除')
      },
      fail: (data, code) => {
        console.error(`数据清除失败: ${code}`)
      }
    })
  }
}

// 导出单例
export default new DataStore()

