"""
六维评分引擎
- 姿势准确度 / 力量传递 / 速度效率 / 击球角度 / 运动链协调 / 伤病安全
- 基于骨骼角度序列 + DTW 对比标准模板
"""
from dataclasses import dataclass

import numpy as np

from pose_estimator import (
    FramePose,
    PoseEstimator,
    VideoAnalysis,
    joint_speed_series,
    landmark_distance_2d,
)


@dataclass
class DimensionScore:
    """单维度评分"""
    name: str
    score: float          # 0-100
    weight: float         # 权重
    details: str          # 评语
    suggestions: list[str] = None

    def __post_init__(self):
        if self.suggestions is None:
            self.suggestions = []


@dataclass
class ScoringResult:
    """六维评分结果"""
    total_score: float
    dimensions: dict[str, DimensionScore]
    hit_frame_idx: int
    swing_phases: dict[str, int]  # {prep, hit, follow}


# 标准角度参考值（正手高远球为例）
STANDARD_ANGLES = {
    "right_elbow": {"prep": 160, "hit": 155, "follow": 140},
    "right_shoulder": {"prep": 45, "hit": 90, "follow": 60},
    "right_knee": {"prep": 160, "hit": 150, "follow": 160},
    "right_hip": {"prep": 170, "hit": 155, "follow": 170},
    "trunk_tilt": {"prep": 10, "hit": 25, "follow": 15},
}

# 维度权重
DIMENSION_WEIGHTS = {
    "posture":      0.20,  # 姿势准确度
    "power_chain":  0.20,  # 力量传递（运动链）
    "speed":        0.15,  # 速度效率
    "angle":        0.15,  # 击球角度
    "kinematic":    0.15,  # 运动链协调
    "safety":       0.15,  # 伤病安全
}


class Scorer:
    """六维评分器"""

    def __init__(self, swing_type: str = "clear"):
        """
        Args:
            swing_type: 击球类型 (clear/smash/drop/drive/lob/serve/net_shot)
        """
        self.swing_type = swing_type

    def score(self, analysis: VideoAnalysis) -> ScoringResult:
        """对整个挥拍视频进行六维评分"""
        poses = analysis.frame_poses
        if len(poses) < 3:
            return self._default_result()

        # 检测挥拍阶段
        prep_idx, hit_idx, follow_idx = PoseEstimator.extract_swing_frames(poses)
        phases = {"prep": prep_idx, "hit": hit_idx, "follow": follow_idx}

        # 获取各阶段角度
        phase_angles = {}
        for phase_name, idx in phases.items():
            if idx < len(poses):
                phase_angles[phase_name] = poses[idx].angles
            else:
                phase_angles[phase_name] = {}

        # 计算六维评分
        dims = {}
        dims["posture"] = self._score_posture(phase_angles)
        dims["power_chain"] = self._score_power_chain(poses, phases)
        dims["speed"] = self._score_speed(poses, phases)
        dims["angle"] = self._score_angle(phase_angles)
        dims["kinematic"] = self._score_kinematic(poses, phases)
        dims["safety"] = self._score_safety(phase_angles)

        # 加权总分
        total = sum(dims[k].score * dims[k].weight for k in dims)

        return ScoringResult(
            total_score=round(total, 1),
            dimensions=dims,
            hit_frame_idx=hit_idx,
            swing_phases=phases,
        )

    def _score_posture(self, phase_angles: dict) -> DimensionScore:
        """姿势准确度：各关节角度与标准值的偏差"""
        standard = STANDARD_ANGLES
        deviations = []
        details_parts = []

        for joint, std_vals in standard.items():
            hit_angles = phase_angles.get("hit", {})
            if joint in hit_angles and joint in std_vals:
                dev = abs(hit_angles[joint] - std_vals["hit"])
                deviations.append(dev)
                if dev > 25:
                    details_parts.append(f"{joint}偏差{dev:.0f}°")

        if deviations:
            avg_dev = np.mean(deviations)
            # 使用温和的扣分曲线：
            # 5°偏差 → 95分，10° → 87分，20° → 72分，30° → 55分
            score = max(40, 100 - avg_dev * 1.2 - max(0, avg_dev - 10) * 0.8)
        else:
            score = 70  # 数据不足给中等偏上

        suggestions = []
        if details_parts:
            suggestions.append(f"注意调整：{', '.join(details_parts[:3])}")

        return DimensionScore(
            name="姿势准确度", score=round(score, 1),
            weight=DIMENSION_WEIGHTS["posture"],
            details="; ".join(details_parts) if details_parts else "姿势标准，动作规范",
            suggestions=suggestions,
        )

    def _score_power_chain(self, poses: list[FramePose],
                           phases: dict) -> DimensionScore:
        """力量传递：运动链速度传递效率（脚踝→髋→肩→肘→腕）"""
        if len(poses) < 5:
            return DimensionScore(
                name="力量传递", score=70,
                weight=DIMENSION_WEIGHTS["power_chain"],
                details="数据不足")

        # 计算各关节点速度峰值
        joint_indices = {
            "ankle": 28, "hip": 24, "shoulder": 12, "elbow": 14, "wrist": 16
        }
        peak_speeds = {}
        for joint_name, idx in joint_indices.items():
            speeds = joint_speed_series(poses, idx)
            peak_speeds[joint_name] = max(speeds) if speeds else 0

        # 检查鞭打效应：速度应从近端向远端递增
        chain_order = ["ankle", "hip", "shoulder", "elbow", "wrist"]
        chain_speeds = [peak_speeds.get(j, 0) for j in chain_order]

        # 计算传递效率：考虑速度递增的比例和递增的幅度
        correct_transfers = 0
        total_gain_ratio = 0.0
        for i in range(len(chain_speeds) - 1):
            if chain_speeds[i] > 0:
                ratio = chain_speeds[i+1] / chain_speeds[i]
                if ratio >= 0.7:  # 允许 30% 容差（更宽松）
                    correct_transfers += 1
                    # 速度增加的幅度越大越好，理想值约 1.2-1.5
                    gain = min(ratio, 2.0) / 1.5  # 归一化
                    total_gain_ratio += min(gain, 1.0)
            else:
                # 近端速度为0（可能检测问题），不算失败
                correct_transfers += 1
                total_gain_ratio += 0.5

        efficiency = correct_transfers / max(len(chain_speeds) - 1, 1)
        gain_score = total_gain_ratio / max(len(chain_speeds) - 1, 1)
        # 综合效率和增益，基准分 65 分起步
        score = 65 + efficiency * 20 + gain_score * 15
        score = max(50, min(100, score))

        suggestions = []
        if efficiency < 0.5:
            suggestions.append("力量传递不连贯，注意从蹬地开始的发力顺序")
        elif efficiency < 0.75:
            suggestions.append("力量传递基本连贯，可以进一步优化发力顺序")

        return DimensionScore(
