/**
 * 挥拍检测算法
 * 参考 BadminSense 项目的运动链分析思路，适配 IMU 传感器数据
 *
 * 核心原理：
 * 1. 基于加速度峰值检测挥拍开始/结束
 * 2. 基于角速度峰值检测击球瞬间
 * 3. 挥拍时长判断 (80ms - 400ms)
 * 4. 连续挥拍去重
 */

import { DEFAULT_THRESHOLDS } from './constants'

class SwingDetector {
  constructor() {
    // 阈值配置
    this.accelThreshold = DEFAULT_THRESHOLDS.ACCEL_PEAK
    this.gyroThreshold = DEFAULT_THRESHOLDS.GYRO_PEAK
    this.minDuration = DEFAULT_THRESHOLDS.SWING_MIN_DURATION
    this.maxDuration = DEFAULT_THRESHOLDS.SWING_MAX_DURATION

    // 状态
    this.isSwinging = false
    this.swingStartTime = null
    this.lastSwingTime = null
    this.cooldownMs = 300 // 挥拍间最小间隔

    // 数据缓冲
    this.dataBuffer = []
    this.maxBufferSize = 50

    // 回调
    this.onSwingDetected = null
  }

  /**
   * 处理传感器数据
   * @param {Object} fusedData - 融合后的传感器数据
   */
  processData(fusedData) {
    const { accel, gyro, magnitude } = fusedData
    const now = Date.now()

    // 添加到缓冲区
    this.dataBuffer.push({
      timestamp: now,
      accelMag: magnitude.accel,
      gyroMag: magnitude.gyro,
      accel,
      gyro
    })

    // 限制缓冲区大小
    if (this.dataBuffer.length > this.maxBufferSize) {
      this.dataBuffer.shift()
    }

    // 检测挥拍
    this.detectSwing(now, magnitude)
  }

  /**
   * 检测挥拍动作
   */
  detectSwing(now, magnitude) {
    // 检查冷却期
    if (this.lastSwingTime && (now - this.lastSwingTime) < this.cooldownMs) {
      return
    }

    // 挥拍开始检测：加速度超过阈值
    if (!this.isSwinging && magnitude.accel > this.accelThreshold) {
      this.isSwinging = true
      this.swingStartTime = now
    }

    // 挥拍结束检测
    if (this.isSwinging) {
      const duration = now - this.swingStartTime

      // 检查挥拍时长
      if (duration > this.minDuration) {
        // 检查角速度峰值（击球瞬间）
        if (magnitude.gyro > this.gyroThreshold * 0.8) {
          this.completeSwing(now, duration)
          return
        }

        // 超时结束
        if (duration > this.maxDuration) {
          this.completeSwing(now, duration)
          return
        }
      }

      // 加速度回落过快，取消挥拍
      if (duration < this.minDuration && magnitude.accel < this.accelThreshold * 0.5) {
        this.isSwinging = false
        this.swingStartTime = null
      }
    }
  }

  /**
   * 完成挥拍检测
   */
  completeSwing(endTime, duration) {
    this.isSwinging = false
    this.lastSwingTime = endTime

    // 计算挥拍强度
    const intensity = this.calculateIntensity()

    // 分析挥拍特征
    const features = this.analyzeSwingFeatures()

    const swingData = {
      startTime: this.swingStartTime,
      endTime: endTime,
      duration: duration,
      intensity: intensity,
      features: features,
      peakAccel: this.getPeakAccel(),
      peakGyro: this.getPeakGyro()
    }

    // 回调
    if (this.onSwingDetected) {
      this.onSwingDetected(swingData)
    }

    // 重置
    this.swingStartTime = null

    return swingData
  }

  /**
   * 计算挥拍强度
   * 参考 BadminSense 的力量传递评分思路
   */
  calculateIntensity() {
    const recentData = this.dataBuffer.slice(-10)
    if (recentData.length === 0) return 0

    // 计算平均加速度幅值
    const avgAccel = recentData.reduce((sum, d) => sum + d.accelMag, 0) / recentData.length

    // 归一化到 0-100
    const normalized = Math.min(100, (avgAccel / this.accelThreshold) * 50)

    return Math.round(normalized)
  }

  /**
   * 分析挥拍特征
   * 参考 BadminSense 的运动链分析
   */
  analyzeSwingFeatures() {
    const recentData = this.dataBuffer.slice(-15)
    if (recentData.length < 3) return {}

    // 分析加速度变化趋势
    const accelTrend = this.analyzeTrend(recentData.map(d => d.accelMag))

    // 分析角速度变化趋势
    const gyroTrend = this.analyzeTrend(recentData.map(d => d.gyroMag))

    // 分析挥拍方向（基于加速度分量）
    const direction = this.analyzeDirection(recentData)

    return {
      accelTrend,
      gyroTrend,
      direction,
      isSmooth: accelTrend.smoothness > 0.6
    }
  }

  /**
   * 分析数据趋势
   */
  analyzeTrend(values) {
    if (values.length < 2) return { increasing: false, smoothness: 0 }

    let increasing = 0
    let decreasing = 0

    for (let i = 1; i < values.length; i++) {
      if (values[i] > values[i - 1]) increasing++
      else decreasing++
    }

    // 计算平滑度（变化的均匀程度）
    const avg = values.reduce((a, b) => a + b, 0) / values.length
    const variance = values.reduce((sum, v) => sum + Math.pow(v - avg, 2), 0) / values.length
    const smoothness = 1 - Math.min(1, variance / (avg * avg + 1))

    return {
      increasing: increasing > decreasing,
      smoothness
    }
  }

  /**
   * 分析挥拍方向
   */
  analyzeDirection(recentData) {
    if (recentData.length < 3) return 'unknown'

    // 使用加速度分量判断方向
    const lastData = recentData[recentData.length - 1]
    const { x, y, z } = lastData.accel

    // 简单的方向判断
    const absX = Math.abs(x)
    const absY = Math.abs(y)
    const absZ = Math.abs(z)

    if (absY > absX && absY > absZ) {
      return y > 0 ? 'down' : 'up'
    } else if (absX > absZ) {
      return 'horizontal'
    } else {
      return 'forward'
    }
  }

  /**
   * 获取加速度峰值
   */
  getPeakAccel() {
    if (this.dataBuffer.length === 0) return 0
    return Math.max(...this.dataBuffer.map(d => d.accelMag))
  }

  /**
   * 获取角速度峰值
   */
  getPeakGyro() {
    if (this.dataBuffer.length === 0) return 0
    return Math.max(...this.dataBuffer.map(d => d.gyroMag))
  }

  /**
   * 设置阈值
   */
  setThresholds(accelThreshold, gyroThreshold) {
    this.accelThreshold = accelThreshold
    this.gyroThreshold = gyroThreshold
  }

  /**
   * 重置状态
   */
  reset() {
    this.isSwinging = false
    this.swingStartTime = null
    this.lastSwingTime = null
    this.dataBuffer = []
  }
}

// 导出单例
export default new SwingDetector()

/**
 * 击球特征提取模块
 * 参考 BadminSense 项目的六维评分思路，从 IMU 数据中提取特征
 *
 * 提取的特征：
 * 1. 加速度特征（峰值、均值、标准差、斜率）
 * 2. 角速度特征（峰值、均值、标准差、斜率）
 * 3. 方向特征（up/down/horizontal）
 * 4. 挥拍角度特征（steep/high/flat/gentle）
 * 5. 能量特征
 */

class FeatureExtractor {
  constructor() {
    // 特征模板（用于分类）
    this.featureTemplates = {
      highClear: {
        accelPeak: { min: 15, max: 25 },
        gyroPeak: { min: 200, max: 350 },
        duration: { min: 150, max: 300 },
        direction: 'up',
        angle: 'steep'
      },
      smash: {
        accelPeak: { min: 20, max: 35 },
        gyroPeak: { min: 300, max: 500 },
        duration: { min: 80, max: 150 },
        direction: 'down',
        angle: 'steep'
      },
      drive: {
        accelPeak: { min: 12, max: 20 },
        gyroPeak: { min: 150, max: 250 },
        duration: { min: 100, max: 200 },
        direction: 'horizontal',
        angle: 'flat'
      },
      lift: {
        accelPeak: { min: 10, max: 18 },
        gyroPeak: { min: 120, max: 200 },
        duration: { min: 150, max: 250 },
        direction: 'up',
        angle: 'gentle'
      },
      drop: {
        accelPeak: { min: 8, max: 15 },
        gyroPeak: { min: 100, max: 180 },
        duration: { min: 120, max: 220 },
        direction: 'down',
        angle: 'gentle'
      }
    }
  }

  /**
   * 从挥拍数据中提取特征
   * @param {Object} swingData - 挥拍检测数据
   * @param {Array} dataBuffer - 传感器数据缓冲
   * @returns {Object} 提取的特征
   */
  extract(swingData, dataBuffer) {
    // 获取挥拍期间的数据
    const swingDataPoints = this.getSwingDataPoints(swingData, dataBuffer)

    if (swingDataPoints.length < 3) {
      return this.getDefaultFeatures()
    }

    // 提取各维度特征
    const accelFeatures = this.extractAccelFeatures(swingDataPoints)
    const gyroFeatures = this.extractGyroFeatures(swingDataPoints)
    const direction = this.extractDirection(swingDataPoints)
    const angle = this.extractAngle(swingDataPoints, swingData)
    const energy = this.extractEnergy(swingDataPoints)

    return {
      accel: accelFeatures,
      gyro: gyroFeatures,
      direction,
      angle,
      energy,
      duration: swingData.duration,
      intensity: swingData.intensity
    }
  }

  /**
   * 获取挥拍期间的数据点
   */
  getSwingDataPoints(swingData, dataBuffer) {
    return dataBuffer.filter(d =>
      d.timestamp >= swingData.startTime &&
      d.timestamp <= swingData.endTime
    )
  }

  /**
   * 提取加速度特征
   * 参考 BadminSense 的速度效率评分
   */
  extractAccelFeatures(dataPoints) {
    const accelMags = dataPoints.map(d => d.accelMag)

    return {
      peak: Math.max(...accelMags),
      mean: this.mean(accelMags),
      std: this.std(accelMags),
      slope: this.calculateSlope(accelMags),
      rms: this.rms(accelMags)
    }
  }

  /**
   * 提取角速度特征
   * 参考 BadminSense 的运动链协调评分
   */
  extractGyroFeatures(dataPoints) {
    const gyroMags = dataPoints.map(d => d.gyroMag)

    return {
      peak: Math.max(...gyroMags),
      mean: this.mean(gyroMags),
      std: this.std(gyroMags),
      slope: this.calculateSlope(gyroMags),
      rms: this.rms(gyroMags)
    }
  }

  /**
   * 提取方向特征
   * 参考 BadminSense 的击球角度评分
   */
  extractDirection(dataPoints) {
    if (dataPoints.length < 2) return 'unknown'

    // 计算加速度分量的平均值
    const avgX = dataPoints.reduce((sum, d) => sum + d.accel.x, 0) / dataPoints.length
    const avgY = dataPoints.reduce((sum, d) => sum + d.accel.y, 0) / dataPoints.length
    const avgZ = dataPoints.reduce((sum, d) => sum + d.accel.z, 0) / dataPoints.length

    // 判断主要方向
    const absX = Math.abs(avgX)
    const absY = Math.abs(avgY)
    const absZ = Math.abs(avgZ)

    if (absY > absX && absY > absZ) {
      return avgY > 0 ? 'down' : 'up'
    } else if (absX > absZ) {
      return 'horizontal'
    } else {
      return 'forward'
    }
  }

  /**
   * 提取挥拍角度特征
   */
  extractAngle(dataPoints, swingData) {
    // 基于角速度和加速度的关系判断挥拍角度
    const peakGyro = Math.max(...dataPoints.map(d => d.gyroMag))
    const peakAccel = Math.max(...dataPoints.map(d => d.accelMag))

    // 角速度与加速度的比值
    const ratio = peakGyro / (peakAccel + 0.001)

    if (ratio > 20) return 'steep'
    if (ratio > 12) return 'high'
    if (ratio > 6) return 'flat'
    return 'gentle'
  }

  /**
   * 提取能量特征
   * 参考 BadminSense 的力量传递评分
   */
  extractEnergy(dataPoints) {
    const accelEnergies = dataPoints.map(d => 0.5 * d.accelMag * d.accelMag)
    const gyroEnergies = dataPoints.map(d => 0.5 * d.gyroMag * d.gyroMag)

    return {
      accelTotal: accelEnergies.reduce((a, b) => a + b, 0),
      gyroTotal: gyroEnergies.reduce((a, b) => a + b, 0),
      peakPower: Math.max(...dataPoints.map(d => d.accelMag * d.gyroMag))
    }
  }

  /**
   * 计算斜率（变化率）
   */
  calculateSlope(values) {
    if (values.length < 2) return 0

    let sumXY = 0
    let sumX = 0
    let sumY = 0
    let sumX2 = 0

    for (let i = 0; i < values.length; i++) {
      sumXY += i * values[i]
      sumX += i
      sumY += values[i]
      sumX2 += i * i
    }

    const n = values.length
    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX)

    return slope
  }

  /**
   * 计算均值
   */
  mean(values) {
    return values.reduce((a, b) => a + b, 0) / values.length
  }

  /**
   * 计算标准差
   */
  std(values) {
    const avg = this.mean(values)
    const squareDiffs = values.map(v => Math.pow(v - avg, 2))
    return Math.sqrt(this.mean(squareDiffs))
  }

  /**
   * 计算均方根
   */
  rms(values) {
    const squares = values.map(v => v * v)
    return Math.sqrt(this.mean(squares))
  }

  /**
   * 获取默认特征
   */
  getDefaultFeatures() {
    return {
      accel: { peak: 0, mean: 0, std: 0, slope: 0, rms: 0 },
      gyro: { peak: 0, mean: 0, std: 0, slope: 0, rms: 0 },
      direction: 'unknown',
      angle: 'flat',
      energy: { accelTotal: 0, gyroTotal: 0, peakPower: 0 },
      duration: 0,
      intensity: 0
    }
  }

  /**
   * 与模板进行相似度比较
   */
  compareWithTemplate(features, templateName) {
    const template = this.featureTemplates[templateName]
    if (!template) return 0

    let score = 0
    let totalWeight = 0

    // 加速度峰值匹配
    if (features.accel.peak >= template.accelPeak.min &&
        features.accel.peak <= template.accelPeak.max) {
      score += 25
    }
    totalWeight += 25

    // 角速度峰值匹配
    if (features.gyro.peak >= template.gyroPeak.min &&
        features.gyro.peak <= template.gyroPeak.max) {
      score += 25
    }
    totalWeight += 25

    // 时长匹配
    if (features.duration >= template.duration.min &&
        features.duration <= template.duration.max) {
      score += 20
    }
    totalWeight += 20

    // 方向匹配
    if (features.direction === template.direction) {
      score += 15
    }
    totalWeight += 15

    // 角度匹配
    if (features.angle === template.angle) {
      score += 15
    }
    totalWeight += 15

    return (score / totalWeight) * 100
  }
}

// 导出单例
export default new FeatureExtractor()

/**
 * 击球类型分类器
 * 参考 BadminSense 项目的评分思路，基于特征匹配进行分类
 *
 * 分类流程：
 * 1. 提取挥拍特征
 * 2. 与各击球类型模板比较
 * 3. 选择相似度最高的类型
 * 4. 计算置信度
 * 5. 时序平滑（防止抖动）
 */

import featureExtractor from './feature-extractor'
import { SHOT_TYPES, SHOT_NAMES } from './constants'

class ShotClassifier {
  constructor() {
    // 分类结果
    this.lastClassification = null
    this.classificationHistory = []
    this.maxHistoryLength = 5

    // 置信度阈值
    this.confidenceThreshold = 60

    // 回调
    this.onClassification = null
  }

  /**
   * 分类击球类型
   * @param {Object} swingData - 挥拍数据
   * @param {Array} dataBuffer - 传感器数据缓冲
   * @returns {Object} 分类结果
   */
  classify(swingData, dataBuffer) {
    // 1. 提取特征
    const features = featureExtractor.extract(swingData, dataBuffer)

    // 2. 与所有模板比较
    const scores = {}
    for (const templateName of Object.values(SHOT_TYPES)) {
      scores[templateName] = featureExtractor.compareWithTemplate(features, templateName)
    }

    // 3. 选择最高分的类型
    let bestType = SHOT_TYPES.HIGH_CLEAR
    let bestScore = 0

    for (const [type, score] of Object.entries(scores)) {
      if (score > bestScore) {
        bestScore = score
        bestType = type
      }
    }

    // 4. 计算置信度
    const confidence = this.calculateConfidence(scores, bestScore)

    // 5. 时序平滑
    const smoothedType = this.temporalSmoothing(bestType, confidence)

    const result = {
      type: smoothedType,
      typeName: SHOT_NAMES[smoothedType],
      confidence: confidence,
      scores: scores,
      features: features
    }

    // 更新历史
    this.updateHistory(result)

    // 回调
    if (this.onClassification) {
      this.onClassification(result)
    }

    return result
  }

  /**
   * 计算置信度
   * 参考 BadminSense 的评分归一化方法
   */
  calculateConfidence(scores, bestScore) {
    // 计算所有分数的标准差
    const allScores = Object.values(scores)
    const mean = allScores.reduce((a, b) => a + b, 0) / allScores.length
    const variance = allScores.reduce((sum, s) => sum + Math.pow(s - mean, 2), 0) / allScores.length
    const std = Math.sqrt(variance)

    // 如果标准差很小，说明区分度低，降低置信度
    const discrimination = Math.min(1, std / 20)

    // 基础置信度
    let confidence = bestScore * discrimination

    // 如果最高分与次高分差距大，增加置信度
    const sortedScores = allScores.sort((a, b) => b - a)
    if (sortedScores.length > 1) {
      const gap = sortedScores[0] - sortedScores[1]
      confidence += gap * 0.3
    }

    return Math.min(100, Math.max(0, confidence))
  }

  /**
   * 时序平滑
   * 防止分类结果频繁抖动
   */
  temporalSmoothing(currentType, confidence) {
    // 低置信度时保持上一次的结果
    if (confidence < this.confidenceThreshold && this.lastClassification) {
      return this.lastClassification.type
    }

    // 检查历史一致性
    const recentTypes = this.classificationHistory.slice(-3).map(h => h.type)
    const typeCount = recentTypes.filter(t => t === currentType).length

    // 如果最近3次中有2次是同一类型，采用当前结果
    if (typeCount >= 2 || confidence > 80) {
      return currentType
    }

    // 否则保持上一次的结果
    return this.lastClassification ? this.lastClassification.type : currentType
  }

  /**
   * 更新分类历史
   */
  updateHistory(result) {
    this.classificationHistory.push({
      type: result.type,
      confidence: result.confidence,
      timestamp: Date.now()
    })

    // 限制历史长度
    if (this.classificationHistory.length > this.maxHistoryLength) {
      this.classificationHistory.shift()
    }

    this.lastClassification = result
  }

  /**
   * 获取最近的分类统计
   */
  getRecentStats() {
    if (this.classificationHistory.length === 0) {
      return {
        highClear: 0,
        smash: 0,
        drive: 0,
        lift: 0,
        drop: 0
      }
    }

    const stats = {
      highClear: 0,
      smash: 0,
      drive: 0,
      lift: 0,
      drop: 0
    }

    this.classificationHistory.forEach(h => {
      stats[h.type]++
    })

    return stats
  }

  /**
   * 重置分类器
   */
  reset() {
    this.lastClassification = null
    this.classificationHistory = []
  }
}

// 导出单例
export default new ShotClassifier()

