/**
 * 工具函数模块
 * 包含震动反馈、时间格式化等通用功能
 */

import vibrator from '@system.vibrator'

class Utils {
  /**
   * 震动反馈
   * @param {number} duration - 震动时长 (ms)
   */
  static vibrate(duration = 50) {
    vibrator.vibrate({
      mode: 'short',
      vibrateTime: duration,
      fail: (data, code) => {
        console.error(`震动失败: ${code}`)
      }
    })
  }

  /**
   * 格式化时长
   * @param {number} seconds - 秒数
   * @returns {string} 格式化后的时长 (MM:SS)
   */
  static formatDuration(seconds) {
    const mins = Math.floor(seconds / 60).toString().padStart(2, '0')
    const secs = (seconds % 60).toString().padStart(2, '0')
    return `${mins}:${secs}`
  }

  /**
   * 格式化日期
   * @param {Date|string|number} date - 日期
   * @returns {string} 格式化后的日期 (YYYY-MM-DD)
   */
  static formatDate(date) {
    const d = new Date(date)
    const year = d.getFullYear()
    const month = (d.getMonth() + 1).toString().padStart(2, '0')
    const day = d.getDate().toString().padStart(2, '0')
    return `${year}-${month}-${day}`
  }

  /**
   * 格式化时间
   * @param {Date|string|number} date - 日期
   * @returns {string} 格式化后的时间 (HH:MM:SS)
   */
  static formatTime(date) {
    const d = new Date(date)
    const hours = d.getHours().toString().padStart(2, '0')
    const mins = d.getMinutes().toString().padStart(2, '0')
    const secs = d.getSeconds().toString().padStart(2, '0')
    return `${hours}:${mins}:${secs}`
  }

  /**
   * 计算均值
   * @param {number[]} values - 数值数组
   * @returns {number} 均值
   */
  static mean(values) {
    if (values.length === 0) return 0
    return values.reduce((a, b) => a + b, 0) / values.length
  }

  /**
   * 计算标准差
   * @param {number[]} values - 数值数组
   * @returns {number} 标准差
   */
  static std(values) {
    if (values.length === 0) return 0
    const avg = Utils.mean(values)
    const squareDiffs = values.map(v => Math.pow(v - avg, 2))
    return Math.sqrt(Utils.mean(squareDiffs))
  }

  /**
   * 限制数值范围
   * @param {number} value - 输入值
   * @param {number} min - 最小值
   * @param {number} max - 最大值
   * @returns {number} 限制后的值
   */
  static clamp(value, min, max) {
    return Math.min(Math.max(value, min), max)
  }

  /**
   * 线性插值
   * @param {number} start - 起始值
   * @param {number} end - 结束值
   * @param {number} t - 插值系数 (0-1)
   * @returns {number} 插值结果
   */
  static lerp(start, end, t) {
    return start + (end - start) * t
  }

  /**
   * 计算向量幅值
   * @param {Object} vector - 向量 {x, y, z}
   * @returns {number} 幅值
   */
  static magnitude(vector) {
    return Math.sqrt(vector.x * vector.x + vector.y * vector.y + vector.z * vector.z)
  }

  /**
   * 生成唯一 ID
   * @returns {string} 唯一 ID
   */
  static generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2)
  }

  /**
   * 深拷贝对象
   * @param {Object} obj - 源对象
   * @returns {Object} 拷贝后的对象
   */
  static deepClone(obj) {
    return JSON.parse(JSON.stringify(obj))
  }

  /**
   * 防抖函数
   * @param {Function} fn - 要防抖的函数
   * @param {number} delay - 延迟时间 (ms)
   * @returns {Function} 防抖后的函数
   */
  static debounce(fn, delay = 300) {
    let timer = null
    return function (...args) {
      if (timer) clearTimeout(timer)
      timer = setTimeout(() => fn.apply(this, args), delay)
    }
  }

  /**
   * 节流函数
   * @param {Function} fn - 要节流的函数
   * @param {number} interval - 间隔时间 (ms)
   * @returns {Function} 节流后的函数
   */
  static throttle(fn, interval = 100) {
    let lastTime = 0
    return function (...args) {
      const now = Date.now()
      if (now - lastTime >= interval) {
        lastTime = now
        return fn.apply(this, args)
      }
    }
  }
}

