extern FeatureRegistryTableHandle g_ajs_features_registry;
int regist_quickapp_features(QApplicationHandle handle,
    FeatureRegistryHandle hRegistry,
    void* user_data)
{
    FeatureRegisterFeatures(hRegistry, g_ajs_features_registry);
    return 0;
